PROGRAM alarm_ctrl
VAR_INPUT
    Trip : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Alarm : BOOL;
END_VAR
VAR
    TripPrev : BOOL;
END_VAR
VAR CONSTANT
    T_ON : TIME := T#5s;
END_VAR

IF Trip AND NOT TripPrev THEN
    Alarm := TRUE;
ELSIF Reset AND Trip THEN
    Alarm := TRUE;
ELSIF Reset AND NOT Trip THEN
    Alarm := FALSE;
END_IF;

TripPrev := Trip;

END_PROGRAM

