PROGRAM elevator
VAR_INPUT
    CallUp : BOOL;
    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
END_VAR
VAR_OUTPUT
    MotorUp : BOOL;
    MotorDown : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

CASE State OF
    0: // At-bottom
        IF CallUp AND DoorClosed THEN
            State := 1;
        END_IF;
    1: // Moving-up
        IF AtTop OR NOT DoorClosed THEN
            State := 2;
        END_IF;
    2: // At-top
        IF CallDown AND DoorClosed THEN
            State := 3;
        END_IF;
    3: // Moving-down
        IF AtBottom OR NOT DoorClosed THEN
            State := 0;
        END_IF;
END_CASE;

IF NOT DoorClosed THEN
    MotorUp := FALSE;
    MotorDown := FALSE;
ELSIF State = 1 THEN
    MotorUp := TRUE;
    MotorDown := FALSE;
ELSIF State = 3 THEN
    MotorUp := FALSE;
    MotorDown := TRUE;
ELSE
    MotorUp := FALSE;
    MotorDown := FALSE;
END_IF;

END_PROGRAM

PROGRAM elevator
VAR_INPUT
    CallUp : BOOL;
    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
END_VAR
VAR_OUTPUT
    MotorUp : BOOL;
    MotorDown : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

CASE State OF
    0: // At-bottom
        IF CallUp AND DoorClosed THEN
            State := 1;
        END_IF;
        MotorUp := FALSE;
        MotorDown := FALSE;

    1: // Moving-up
        IF NOT DoorClosed OR AtTop THEN
            State := AtTop ? 2 : State;
        END_IF;
        MotorUp := DoorClosed AND NOT AtTop;
        MotorDown := FALSE;

    2: // At-top
        IF CallDown AND DoorClosed THEN
            State := 3;
        END_IF;
        MotorUp := FALSE;
        MotorDown := FALSE;

    3: // Moving-down
        IF NOT DoorClosed OR AtBottom THEN
            State := AtBottom ? 0 : State;
        END_IF;
        MotorUp := FALSE;
        MotorDown := DoorClosed AND NOT AtBottom;
END_CASE;

END_PROGRAM

PROGRAM elevator
VAR_INPUT
    CallUp : BOOL;
    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
END_VAR
VAR_OUTPUT
    MotorUp : BOOL;
    MotorDown : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

CASE State OF
    0: // At-bottom
        IF CallUp AND DoorClosed THEN
            State := 1;
        END_IF;
    1: // Moving-up
        IF Not DoorClosed OR AtTop THEN
            MotorUp := FALSE;
            State := IIF(AtTop, 2, State);
        ELSIF CallDown AND Not AtBottom THEN
            MotorUp := FALSE;
            MotorDown := TRUE;
            State := 3;
        END_IF;
    2: // At-top
        IF CallDown AND DoorClosed THEN
            State := 3;
        END_IF;
    3: // Moving-down
        IF Not DoorClosed OR AtBottom THEN
            MotorDown := FALSE;
            State := IIF(AtBottom, 0, State);
        ELSIF CallUp AND Not AtTop THEN
            MotorUp := TRUE;
            MotorDown := FALSE;
            State := 1;
        END_IF;
END_CASE;

MotorUp := IIF(State=1, TRUE, FALSE);
MotorDown := IIF(State=3, TRUE, FALSE);

END_PROGRAM

PROGRAM elevator
VAR_INPUT
    CallUp : BOOL;
    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
END_VAR
VAR_OUTPUT
    MotorUp : BOOL;
    MotorDown : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    AtBottom : INT := 0;
    Up : INT := 1;
    AtTop : INT := 2;
    Down : INT := 3;
END_VAR

IF NOT DoorClosed THEN
    State := AtBottom;
ELSIF CallUp AND State <= AtBottom THEN
    State := Up;
ELSIF CallDown AND State >= AtTop THEN
    State := Down;
END_IF;

CASE State OF
    AtBottom:
        MotorUp := FALSE;
        MotorDown := FALSE;
    Up:
        MotorUp := TRUE;
        MotorDown := FALSE;
        IF AtTop OR NOT DoorClosed THEN
