        MotorDown := FALSE;

    3: // Moving-down
        IF Not DoorClosed OR AtBottom THEN
            State := AtBottom ? 0 : State;
        ELSIF CallUp AND Not AtTop AND DoorClosed THEN
            State := 1;
        END_IF;
        MotorUp := FALSE;
        MotorDown := AtBottom ? FALSE : TRUE;
END_CASE;

