                State := HEAT;
            END_IF;
        FILL:
            IF Level >= LVL_HIGH THEN
                State := HEAT;
            END_IF;
        HEAT:
            IF Temp >= TEMP_SET AND State < REACT THEN
                State := REACT;
            END_IF;
        REACT:
            IF State < REACT + PT_REACT THEN
                State := REACT;
            ELSIF Level <= LVL_LOW THEN
                State := DRAIN;
            END_IF;
        DRAIN:
            IF Level <= LVL_LOW THEN
                State := IDLE;
            END_IF;
    END_CASE;
END_IF;

CASE State OF
    IDLE:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    FILL:
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    HEAT:
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    REACT:
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    DRAIN:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
END_CASE;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : INT := 3;
END_VAR
VAR
    State : INT;
END_VAR
VAR TON
    T1;
END_VAR

T1(IN := TRUE, PT := T#3s);

CASE State OF
    0: // Idle
        IF NOT EStop THEN
            State := 0;
        ELSIF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;

    1: // Fill
        IF NOT EStop OR Level >= LVL_HIGH OR Level < LIQ_MIN THEN
            State := 0;
        ELSE
            FillValve := TRUE;
        END_IF;

    2: // Heat
        IF NOT EStop OR Temp >= TEMP_SET OR Level < LIQ_MIN THEN
            State := 0;
        ELSE
            Heater := TRUE;
            Agitator := TRUE;
        END_IF;

    3: // React
        IF NOT EStop OR Level < LIQ_MIN OR T1.Q >= PT_REACT THEN
            State := 0;
        ELSE
            Heater := TRUE;
            Agitator := TRUE;
        END_IF;
        T1(IN := TRUE);

    4: // Drain
        IF NOT EStop OR Level <= LVL_LOW OR Level < LIQ_MIN THEN
            State := 0;
        ELSE
            DrainValve := TRUE;
        END_IF;
END_CASE;

IF NOT EStop OR Level < LIQ_MIN THEN
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

END_PROGRAM

