    StartPB : BOOL;
    StopPB  : BOOL;
    EStop   : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        IF StopPB OR NOT EStop THEN
            State := 0;
        ELSIF StartPB AND EStop THEN
            State := 1;
        END_IF;

    1:
        C1 := FALSE;
        C2 := TRUE;
        IF StopPB OR NOT EStop THEN
            State := 0;
        ELSIF State = 1 AND Time >= PT_SEQ THEN
            State := 2;
        END_IF;

    2:
        C1 := TRUE;
        C2 := TRUE;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM conveyor_seq
VAR_INPUT
