    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

CASE State OF
    0:
        IF (NOT EStop OR StopPB) THEN
            State := 0;
        ELSIF StartPB AND EStop THEN
            State := 1;
        END_IF;
    1:
        IF (NOT EStop OR StopPB) THEN
            State := 0;
        ELSIF State = 1 AND T#2s >= PT_SEQ THEN
            State := 2;
        END_IF;
    2:
        IF (NOT EStop OR StopPB) THEN
            State := 0;
        END_IF;
END_CASE;

IF State >= 1 AND EStop THEN
    C2 := TRUE;
ELSE
    C2 := FALSE;
END_IF;

IF State >= 2 AND EStop THEN
    C1 := TRUE;
ELSE
    C1 := FALSE;
END_IF;

END_PROGRAM

