IF NOT EStop THEN
    State := 0;
ELSIF StopPB OR (State >= 1 AND NOT C2) THEN
    State := 0;
ELSIF StartPB AND State <= 1 THEN
    State := 1;
ELSIF State = 1 AND T#2s >= PT_SEQ THEN
    State := 2;
END_IF;

