PROGRAM burner
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
    Flame : BOOL;
END_VAR
VAR_OUTPUT
    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_PURGE : TIME := T#3s;
    PT_IGN : TIME := T#2s;
END_VAR

IF NOT EStop THEN
    State := 0;
ELSIF StartPB AND EStop AND State = 0 THEN
    State := 1;
ELSIF StopPB OR (NOT EStop) THEN
    State := 0;
END_IF;

CASE State OF
    0:
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;
    1:
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF T#3s >= PT_PURGE THEN
            State := 2;
        END_IF;
    2:
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF T#2s >= PT_IGN THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        END_IF;
    3:
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

