        Fuel := TRUE;
        Ignition := TRUE;

    3: // Run
        IF StopPB OR NOT EStop OR NOT Flame THEN
            State := 0;
        END_IF;
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
