    CloseLimit : BOOL;
    Obstruction : BOOL;
END_VAR
VAR_OUTPUT
    MotorOpen : BOOL;
    MotorClose : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    IDLE : INT := 0;
    OPENING : INT := 1;
    CLOSING : INT := 2;
END_VAR

CASE State OF
    IDLE:
        IF CloseCmd AND NOT CloseLimit AND NOT Obstruction THEN
            State := CLOSING;
        ELSIF OpenCmd AND NOT OpenLimit THEN
            State := OPENING;
        END_IF;
    OPENING:
        IF OpenLimit OR Obstruction THEN
            State := IDLE;
        END_IF;
    CLOSING:
        IF CloseLimit OR Obstruction THEN
            State := IDLE;
        END_IF;
END_CASE;

IF State = OPENING THEN
    MotorOpen := TRUE;
    MotorClose := FALSE;
ELSIF State = CLOSING THEN
    MotorOpen := FALSE;
    MotorClose := TRUE;
ELSE
    MotorOpen := FALSE;
    MotorClose := FALSE;
END_IF;

END_PROGRAM

