    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

IF NOT EStop THEN
    State := 0;
ELSIF StopPB OR (State >= 1 AND NOT EStop) THEN
    State := 0;
ELSIF StartPB AND State = 0 THEN
    State := 1;
ELSIF State = 1 AND T#2s <= PT_SEQ THEN
    State := 2;
ELSIF State = 2 AND T#4s <= 2 * PT_SEQ THEN
    State := 3;
END_IF;

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
END_CASE;

END_PROGRAM

